_ANSI = re.compile(r"\033\[[0-9;]*m")


def strip_ansi(s: str) -> str:
    return _ANSI.sub("", s)


# 运行日志着色：命中即返回 tk 文本标签名（None = 默认色）
_LOG_OK_MARKS = ("✓", "models OK", "chat OK")
_LOG_ERR_MARKS = ("失败", "✗", "ERROR", "错误", "Traceback")


def log_line_tag(line: str) -> str | None:
    """判断一行运行日志该用哪个颜色标签：失败→"err"，成功→"ok"，其余→None。

    只检查第一个 "·" 之前的“结论段”（形如
    `[mc] 测试 http://…/v1/chat/completions → chat OK(qwen3.8-flash)`），
    因为 "·" 之后是模型回答正文，正文里出现“失败/OK”等词不该影响这一行的颜色。
    """
    head = line.split("·", 1)[0]
    if any(m in head for m in _LOG_ERR_MARKS):
        return "err"
    if "HTTP 4" in head or "HTTP 5" in head:   # 上游 4xx/5xx 同样算失败
        return "err"
    if any(m in head for m in _LOG_OK_MARKS):
        return "ok"
    return None


def port_free(host: str, port: int) -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        try:
            s.bind((host, port))
            return True
        except OSError:
            return False


def _port_owner_pid(port: int) -> int | None:
    """查占用该端口 LISTEN 的进程 pid（Windows netstat），查不到返回 None。"""
    try:
        out = subprocess.run(["netstat", "-ano", "-p", "TCP"], capture_output=True,
                             timeout=15, text=True, errors="replace").stdout or ""
    except Exception:
        return None
    for line in out.splitlines():
        parts = line.split()
        if len(parts) == 5 and parts[0] == "TCP" and parts[3] == "LISTENING":
            try:
                if int(parts[1].rsplit(":", 1)[1]) == port:
                    return int(parts[4])
            except (ValueError, IndexError):
                continue
    return None


def _pid_command(pid: int) -> str:
    try:
        r = subprocess.run(["powershell", "-NoProfile", "-Command",
                            f"(Get-CimInstance Win32_Process -Filter 'ProcessId={pid}').CommandLine"],
                           capture_output=True, timeout=20, text=True, errors="replace")
        return r.stdout or ""
    except Exception:
        return ""


def probe_local_chat(base_url: str, model: str, timeout: int = 60) -> bool | None:
    """经本地反代低成本探测模型：True 存活 / False 已下线 / None 未知（服务未起/网络错）。
    system+hi 最小请求；只有明确的“模型不存在”类 400 才判死。"""
    import urllib.request
    body = json.dumps({"model": model, "messages": [
        {"role": "system", "content": "you are a helpful assistant"},
        {"role": "user", "content": "hi"}], "max_tokens": 5, "stream": False}).encode()
    req = urllib.request.Request(base_url.rstrip("/") + "/chat/completions", data=body,
                                 headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            d = json.loads(r.read().decode("utf-8", "replace"))
        choices = (d or {}).get("choices") or []
        return True if choices else None
    except Exception as e:  # noqa: BLE001
        msg = ""
        try:
            import urllib.error
            if isinstance(e, urllib.error.HTTPError):
                msg = e.read().decode("utf-8", "replace")[:300]
        except Exception:
            pass
        low = msg.lower()
        if any(k in low for k in ("service info not found", "not exposed", "model not found",
                                  "unknown model", "invalid model", "not registered",
                                  "route missed", "unsupported",
                                  "不存在", "未注册", "不支持", "已下线", "无此模型")):
            return False
        return None


def _post_chat_json(base_url: str, payload: dict, timeout: int) -> tuple[int, str]:
    """POST 到本地反代的 /chat/completions；返回 (status, body_text)。

    传输层失败返回 (-1, 描述)；HTTPError 也把 body 读出来（诊断信息在里面）。
    """
    import urllib.request
    import urllib.error
    req = urllib.request.Request(base_url.rstrip("/") + "/chat/completions",
                                 data=json.dumps(payload).encode(),
                                 headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        try:
            return e.code, e.read().decode("utf-8", "replace")
        except Exception:  # noqa: BLE001
            return e.code, ""
    except Exception as e:  # noqa: BLE001
        return -1, f"{type(e).__name__}: {e}"


def _tool_choice_rejected(status: int, body: str) -> bool:
    """上游是否在抱怨 tool_choice 的格式（而不是别的错）。"""
    if status not in (400, 422):
        return False
    low = (body or "").lower()
    return "tool_choice" in low or "toolchoice" in low


def probe_model_tools(base_url: str, model: str, timeout: int = 90) -> bool | None:
    """经本地反代探测模型是否支持工具调用：True 支持 / False 不支持 / None 未知。

    判据是「强制调用工具」的请求能否返回 tool_calls。但**各通道上游对
    tool_choice 的接受程度不一样**：mc 的官方代理两种协议都接受对象形式，
    而 WorkBuddy(CodeBuddy) 上游是 Go 服务，其 tool_choice 字段类型是 string，
    收到 {"type":"function",...} 这种对象会直接 400
    （`cannot unmarshal object into Go struct field Request.tool_choice of type string`）。
    所以按精度**逐级降级**：

      1. 对象形式 {"type":"function","function":{"name":…}} —— 最精确
      2. 字符串 "required" —— 语义等价（必须调用工具，但不限定哪个），够探测用
      3. 字符串 "auto" —— 只能**证明支持**（真的回了 tool_calls），证不了不支持

    降级只在明确是 tool_choice 格式问题时发生，其它错误（鉴权/模型不存在）直接
    记 None，不浪费请求。
    """
    tool = [{"type": "function",
             "function": {"name": "cap_probe",
                          "description": "能力探测占位工具；被要求时必须调用它。",
                          "parameters": {"type": "object",
                                         "properties": {"ok": {"type": "boolean"}},
                                         "required": ["ok"]}}}]
    base_payload = {"model": model,
                    # 首条必须是 system：WorkBuddy(CodeBuddy) 上游强制要求，
                    # 否则回 400 code 11128「first message is not system prompt」。
                    "messages": [{"role": "system", "content": "you are a helpful assistant"},
                                 {"role": "user", "content": "调用 cap_probe，ok 传 true。"}],
                    "tools": tool, "max_tokens": 200, "stream": False}

    for choice, forced in (({"type": "function", "function": {"name": "cap_probe"}}, True),
                           ("required", True),
                           ("auto", False)):
        status, text = _post_chat_json(base_url, dict(base_payload, tool_choice=choice), timeout)
        if status == -1:                      # 传输层失败：未知
            return None
        if status == 200:
            try:
                d = json.loads(text)
            except Exception:  # noqa: BLE001
                return None
            choices = (d or {}).get("choices") or []
            if not choices:
                return None
            got = bool((choices[0].get("message") or {}).get("tool_calls"))
            if got:
                return True
            # 强制调用却没回 tool_calls → 判定不支持；
            # auto 下没回只能算未知（模型可以合法地选择不调工具）
            return False if forced else None
        if _tool_choice_rejected(status, text):
            continue                          # 换下一种形式重试
        return None                           # 其它错误：未知
    return None


def probe_model_speed(base_url: str, model: str, timeout: int = 90,
                      max_tokens: int = 64) -> dict:
    """快速测一次模型的「首字延迟」和「生成速度」。

    走流式请求，量三个值：
      · first   —— 首字延迟（发出请求 → 第一个 delta 到达），真实测量
      · tps     —— 生成速度（首字之后每秒产出多少 delta）
      · tokens  —— 产出量的口径

    注意速度是**估算**：本网关的流式响应不带 usage（OpenAI 要
    stream_options.include_usage 才有），所以拿不到精确的 completion_tokens，
    只能数 delta 个数当近似。因此返回值带 estimated=True，界面/日志要标明「约」。
    首字延迟不受此影响，是准的。
    """
    import urllib.request
    import urllib.error
    import time as _t
    payload = {"model": model,
               # 首条必须是 system：WorkBuddy(CodeBuddy) 上游强制要求，
               # 否则回 400 code 11128「first message is not system prompt」。
               # 对 mc 等通道也无害（system 会变成 instructions/system）。
               "messages": [{"role": "system", "content": "you are a helpful assistant"},
                            {"role": "user", "content": "用一句话说明什么是HTTP。"}],
               "max_tokens": max_tokens, "stream": True}
    req = urllib.request.Request(
        base_url.rstrip("/") + "/chat/completions",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json", "Accept": "text/event-stream"},
        method="POST")
    t0 = _t.time()
    first = None
    chunks = 0
    usage_tokens = None
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            if r.status != 200:
                return {"error": f"HTTP {r.status}"}
            for raw in r:                      # SSE 逐行读
                line = raw.decode("utf-8", "replace").strip()
                if not line.startswith("data:"):
                    continue
                p = line[5:].strip()
                if p == "[DONE]":
                    break
                try:
                    d = json.loads(p)
                except Exception:  # noqa: BLE001
                    continue
                ch = (d.get("choices") or [{}])[0]
                dl = ch.get("delta") or {}
                if dl.get("content") or dl.get("reasoning_content") or dl.get("tool_calls"):
                    chunks += 1
                    if first is None:
                        first = _t.time() - t0
                u = d.get("usage") or ch.get("usage") or {}
                if u.get("completion_tokens"):
                    usage_tokens = u["completion_tokens"]
    except Exception as e:  # noqa: BLE001
        return {"error": f"{type(e).__name__}: {e}"}
    elapsed = _t.time() - t0
    gen = (elapsed - first) if first is not None else None
    tokens = usage_tokens or chunks
    tps = (tokens / gen) if (gen and gen > 0 and tokens) else None
    return {"first": first, "tps": tps, "tokens": tokens, "elapsed": elapsed,
            "estimated": usage_tokens is None, "error": None}


def _fmt_speed(sp: dict) -> str:
    """把测速结果压成一行短文本（供日志）。"""
    if not sp or sp.get("error"):
        return f"测速失败（{sp.get('error') if sp else '无结果'}）"
    first = sp.get("first")
    tps = sp.get("tps")
    parts = []
    parts.append(f"首字 {first:.2f}s" if isinstance(first, (int, float)) else "首字 —")
    if isinstance(tps, (int, float)):
        parts.append(("约 " if sp.get("estimated") else "") + f"{tps:.1f} t/s")
    else:
        parts.append("速度 —")
    parts.append(f"{sp.get('tokens', 0)} 字")
    return " · ".join(parts)


def refresh_models_startup(s: dict, log=print, local_bases: dict | None = None):
    """每次启动后台刷新各通道模型存活（daemon 线程调用，不阻塞）。
    cb 直连上游逐个探测；rc 取 catalog 即最新；mc/ca/cp 仅在本地服务已起时经本地探测。
    结果写入 settings[{key}_verified]={ts, alive, checked, dead}，dialog 据此标注。
    mc 额外探测工具调用能力（慢，带 TTL 缓存），写入 {key}_verified["tools"]。"""
    local_bases = local_bases or {}
    names = {"cb": "WorkBuddy", "mc": "MonkeyCode", "ca": "华为云", "rc": "小浣熊", "cp": "CatPaw"}
    builtin = {"cb": list(CB_MODEL_CANDIDATES), "mc": list(MC_MODEL_CANDIDATES),
               "ca": list(CA_MODEL_CANDIDATES), "rc": list(RACOON_MODEL_CANDIDATES),
               "cp": list(CP_MODEL_CANDIDATES)}

    def _save(key: str, alive: list, checked: list, dead: list | None = None, extra: dict | None = None):
        prev = s.get(f"{key}_verified") or {}
        rec = {"ts": time.time(), "alive": alive, "checked": checked,
               "dead": dead if dead is not None else [m for m in checked if m not in alive]}
        if extra:
            rec.update(extra)
        else:  # 保留上次的工具探测结果，别被存活刷新抹掉
            for k in ("tools", "tools_ts"):
                if k in prev:
                    rec[k] = prev[k]
        s[f"{key}_verified"] = rec
        try:
            save_settings(s)
        except Exception:
            pass

    # cb：直连上游探测（不依赖本地服务）
    try:
        conv = import_converter()
        resolve = getattr(conv, "resolve_model", lambda m: m)
        cands = list(dict.fromkeys(list(builtin["cb"]) + [(resolve(m) or m) for m in (s.get("cb_models") or [])]))
        res = conv.probe_models(cands) if hasattr(conv, "probe_models") else {}
        alive = [k for k, v in res.items() if v is True]
        dead = [k for k, v in res.items() if v is False]
        _save("cb", alive, list(res.keys()), dead)
        log(f"[models] WorkBuddy 启动刷新：{len(alive)}/{len(res)} 存活"
            + (f" · 已下线：{', '.join(dead)}" if dead else ""))
    except Exception as e:  # noqa: BLE001
        log(f"[models] WorkBuddy 刷新失败：{e}")

    # rc：catalog 即最新（1 次请求，无逐个探测成本）
    try:
        rc = import_raccoon()
        mp = rc.catalog_name_map() if hasattr(rc, "catalog_name_map") else {}
        if mp:
            _save("rc", list(mp.values()), list(mp.values()))
            log(f"[models] 小浣熊启动刷新：catalog {len(mp)} 个（显示名优先）")
        else:
            log("[models] 小浣熊刷新：catalog 不可达，用上回兜底")
    except Exception as e:  # noqa: BLE001
        log(f"[models] 小浣熊刷新失败：{e}")

    # mc/ca/cp：仅服务已起时经本地探测
    for key in ("mc", "ca", "cp"):
        try:
            base = local_bases.get(key)
            if not base:
                log(f"[models] {names[key]}刷新跳过（服务未启动）")
                continue
            cands = list(dict.fromkeys(list(builtin[key]) + list(s.get(f"{key}_models") or [])))
            res = {m: probe_local_chat(base, m) for m in cands}
            alive = [k for k, v in res.items() if v is True]
            dead = [k for k, v in res.items() if v is False]
            extra = None
            # 工具调用能力不在这里探测：每个模型一次请求、很慢（实测每个 5–10s）。
            # 改由模型对话框的「探测工具能力」按钮按需触发，只测勾选的模型。
            _save(key, alive, list(res.keys()), dead, extra)
            log(f"[models] {names[key]} 启动刷新：{len(alive)}/{len(res)} 存活"
                + (f" · 已下线：{', '.join(dead)}" if dead else ""))
        except Exception as e:  # noqa: BLE001
            log(f"[models] {names[key]} 刷新失败：{e}")


def reclaim_stale_port(host: str, port: int, log=print) -> bool:
    """端口被占用时：若占用者是上回没退干净的 BuddyZGateway（含 --serve / GUI / 打包 exe），
    taskkill 关闭后返回 True；若是别的程序或查不到，返回 False（调用方保持报错）。"""
    pid = _port_owner_pid(port)
    if not pid:
        log(f"[port] 端口 {port} 被占用，但查不到占用进程")
        return False
    if pid == os.getpid():
        return False
    cmd = _pid_command(pid)
    if "buddyzgateway" not in cmd.lower():
        log(f"[port] 端口 {port} 被其他程序占用 (pid={pid})，不处理")
        return False
    log(f"[port] 端口 {port} 被残留的 BuddyZGateway 占用 (pid={pid})，正在关闭…")
    try:
        subprocess.run(["taskkill", "/F", "/PID", str(pid)], capture_output=True, timeout=15)
    except Exception as e:  # noqa: BLE001
        log(f"[port] 关闭残留进程失败：{e}")
        return False
    for _ in range(30):
        if port_free(host, port):
            break
        time.sleep(0.2)
    if port_free(host, port):
        log(f"[port] 残留进程已关闭，端口 {port} 已释放，继续启动")
        return True
    log(f"[port] 残留进程已关但端口 {port} 仍被占用")
    return False


def ts() -> str:
    return time.strftime("%H:%M:%S")


class Tee:
    """把 stdout/stderr 同时写到控制台和日志队列（供 GUI 显示）。"""

    def __init__(self):
        self.sink = None          # callable(str)
        self._orig_out = None
        self._orig_err = None

    def install(self, sink):
        self.sink = sink
        self._orig_out = sys.stdout
        self._orig_err = sys.stderr
        sys.stdout = self
        sys.stderr = self

    def write(self, s):
        for h in (self._orig_out, self._orig_err):
            if h is not None:
                try:
                    h.write(s)
                except Exception:
                    pass
        if self.sink:
            try:
                self.sink(s)
            except Exception:
                pass
        return len(s)

    def flush(self):
        for h in (self._orig_out, self._orig_err):
            if h is not None:
                try:
                    h.flush()
                except Exception:
                    pass

    def isatty(self):
        return False

    def reconfigure(self, **_kw):  # 某些依赖会对 stdout 调用它
        pass

    def fileno(self):
        return 1


# ---------------------------------------------------------------------------
# Python 依赖
# ---------------------------------------------------------------------------

REQUIRED_DEPS = [
    ("fastapi", "fastapi"),
    ("uvicorn[standard]", "uvicorn"),
    ("httpx", "httpx"),
    ("python-dotenv", "dotenv"),
    ("pystray", "pystray"),
    ("Pillow", "PIL"),
    # codearts2openai 需要的 DPoP 依赖
    ("PyJWT", "jwt"),
    ("cryptography", "cryptography"),
    ("pywin32", "win32crypt"),
    ("requests", "requests"),
]


def missing_deps() -> list[str]:
    if is_frozen():
        return []  # 依赖已随 exe 打包
    out = []
    for pip_name, mod in REQUIRED_DEPS:
        try:
            if importlib.util.find_spec(mod) is None:
                out.append(pip_name)
        except (ImportError, ValueError):
            out.append(pip_name)
    return out


def _invalidate_import_caches() -> None:
    """pip 装完后让本进程能立刻 import 新模块（find_spec 会吃旧负缓存）。"""
    importlib.invalidate_caches()
    try:
        import site
        for p in (site.getusersitepackages(), *site.getsitepackages()):
            if p:
                site.addsitedir(p)  # 处理 .pth（pywin32.pth 把 win32/ 加进 path）
    except Exception:
        pass


def install_deps(log=print) -> bool:
    """pip 安装缺失依赖；Program Files 下无权限时自动回退 --user。"""
    miss = missing_deps()
    if not miss:
        return True
    log(f"[deps] 正在安装缺失依赖：{' '.join(miss)} …")
    base = [sys.executable, "-m", "pip", "install", "--quiet", "--disable-pip-version-check"] + miss
    for extra in ([], ["--user"]):
        cmd = base + extra
        try:
            p = subprocess.run(cmd, capture_output=True, text=True,
                               encoding="utf-8", errors="replace",
                               creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            if p.returncode == 0:
                _invalidate_import_caches()
                still = missing_deps()
                if still:
                    log(f"[deps] 已安装但本进程仍检测不到：{' '.join(still)}（重启网关即可生效）")
                    return False
                log("[deps] 依赖安装完成")
                return True
            log(f"[deps] pip 输出：{(p.stdout or '')[-500:]} {(p.stderr or '')[-800:]}")
        except Exception as e:  # noqa: BLE001
            log(f"[deps] pip 异常：{e}")
    pkgs = " ".join(p for p, _ in REQUIRED_DEPS)
    log(f"[deps] 依赖安装失败，请手动执行：\"{sys.executable}\" -m pip install {pkgs}")
    return False


