    def make_tray_image():
        try:
            from PIL import Image, ImageDraw
            img = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
            d = ImageDraw.Draw(img)
            d.rounded_rectangle([4, 4, 60, 60], radius=14, fill=(24, 27, 32, 255))
            d.ellipse([12, 18, 30, 36], fill=(34, 197, 94, 255))    # 绿点：OpenAI 通道
            return img
        except Exception:
            return None

        root.deiconify()
        root.lift()
        try:
            root.focus_force()
        except Exception:
            pass

    def create_tray():
        nonlocal tray_icon
        if tray_icon is not None:
            return
        try:
            import pystray
            img = make_tray_image()
            if img is None:
                emit("[tray] 无法生成托盘图标，关闭窗口将直接退出")
                return
            menu = pystray.Menu(
                pystray.MenuItem("显示主窗口", lambda *a: ui(show_from_tray), default=True),
                pystray.MenuItem("▶ 一键启动", lambda *a: ui(lambda: threading.Thread(target=start_all, daemon=True).start())),
                pystray.MenuItem("■ 全部停止", lambda *a: ui(lambda: threading.Thread(target=stop_all, daemon=True).start())),
                pystray.Menu.SEPARATOR,
                pystray.MenuItem("退出", lambda *a: ui(real_exit)),
            )
            tray_icon = pystray.Icon(APP_NAME, img, f"{APP_NAME} · WorkBuddy/MonkeyCode 反代网关", menu)
            threading.Thread(target=tray_icon.run, daemon=True).start()
            emit("[tray] 系统托盘已启用：点 × 缩小到托盘，服务继续运行")
        except Exception as e:  # noqa: BLE001
            tray_icon = None
            emit(f"[tray] 系统托盘不可用（{e}），关闭窗口将直接退出")

