def run_selftest() -> int:
    result: dict = {"ok": False, "steps": {}, "version": VERSION}

    def step(name, ok, info=""):
        result["steps"][name] = {"ok": bool(ok), "info": str(info)[:300]}
        print(("PASS" if ok else "FAIL") + f"  {name}  {info}")

    try:
        rt = materialize()
        step("materialize", True, str(rt))
    except Exception as e:  # noqa: BLE001
        step("materialize", False, e)

    miss = missing_deps()
    step("deps", not miss, "all present" if not miss else f"missing: {miss}")

    s = read_cb_summary()
    result["cb_auth"] = s
    step("cb_auth", bool(s.get("found")), s.get("nickname") or s.get("error") or "not found")

    if not miss:
        try:
            conv = import_converter()
            af = conv.find_auth_file()
            conv.CONFIG["cred"] = conv.CredentialManager(af) if af else None
            step("import_converter", True, type(conv.app).__name__)
        except Exception as e:  # noqa: BLE001
            step("import_converter", False, e)
        try:
            mc = import_monkeycode()
            step("import_monkeycode", True, type(mc.app).__name__)
        except Exception as e:  # noqa: BLE001
            step("import_monkeycode", False, e)
        try:
            ca = import_codearts()
            step("import_codearts", True, type(ca.app).__name__)
        except Exception as e:  # noqa: BLE001
            step("import_codearts", False, e)
        try:
            rc = import_raccoon()
            step("import_raccoon", True, type(rc.app).__name__)
        except Exception as e:  # noqa: BLE001
            step("import_raccoon", False, e)
        try:
            cp = import_catpaw()
            step("import_catpaw", True, type(cp.app).__name__)
        except Exception as e:  # noqa: BLE001
            step("import_catpaw", False, e)
    else:
        step("import_converter", False, "deps missing")
        step("import_monkeycode", False, "deps missing")
        step("import_codearts", False, "deps missing")
        step("import_raccoon", False, "deps missing")
        step("import_catpaw", False, "deps missing")

    result["ok"] = all(v["ok"] for k, v in result["steps"].items() if k in ("materialize", "deps", "import_converter", "import_monkeycode", "import_codearts", "import_raccoon", "import_catpaw"))
    out = app_root() / "selftest_result.json"
    try:
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
        print(f"result file: {out}")
    except OSError:
        pass
    print("SELFTEST " + ("PASS" if result["ok"] else "FAIL"))
    return 0 if result["ok"] else 1


def run_serve(cb_port: int, mc_port: int, ca_port: int, rc_port: int, cp_port: int, host: str):
    materialize()
    os.environ["BUDDYZ_DATA_DIR"] = str(data_dir())
    if missing_deps():
        if not install_deps():
            sys.exit(2)
    _s = load_settings()
    _cb_models = _s.get("cb_models") or []
    _mc_models = _s.get("mc_models") or MC_DEFAULT_MODELS
    _ca_models = _s.get("ca_models") or CA_MODEL_CANDIDATES
    stop_evt = threading.Event()
    svcs = []
    conv = import_converter()
    af = conv.find_auth_file()
    conv.CONFIG["cred"] = conv.CredentialManager(af) if af else None
    conv.CONFIG["log_path"] = str(logs_dir() / "codebuddy2openai.log")
    conv.CONFIG["exposed_models"] = list(_cb_models) if _cb_models else None
    svcs.append(("cb", ProxyService("cb", "cb"), conv.app, cb_port))
    mc = import_monkeycode()
    mc.CONFIG["exposed_models"] = list(_mc_models)
    mc.CONFIG["log_path"] = str(logs_dir() / "monkeycode2openai.log")
    mc.CONFIG["pool_enabled"] = bool(_s.get("mc_pool_enabled", False))
    mc.CONFIG["pool_keys"] = [dict(k) for k in (_s.get("mc_pool") or [])]
    svcs.append(("mc", ProxyService("mc", "mc"), mc.app, mc_port))
    ca = import_codearts()
    ca.CONFIG["local_api_key"] = (_s.get("ca_api_key") or "").strip()
    ca.CONFIG["exposed_models"] = list(_ca_models)
    ca.CONFIG["log_path"] = str(logs_dir() / "codearts2openai.log")
    ca.CONFIG["port"] = ca_port
    svcs.append(("ca", ProxyService("ca", "ca"), ca.app, ca_port))
    _rc_models = _s.get("rc_models") or []
    rc = import_raccoon()
    rc.CONFIG["exposed_models"] = list(_rc_models)
    rc.CONFIG["log_path"] = str(logs_dir() / "raccoon2openai.log")
    rc_dir = (_s.get("rc_auth_dir") or "").strip()
    if rc_dir:
        rc.CONFIG["auth_dir"] = rc_dir
    svcs.append(("rc", ProxyService("rc", "rc"), rc.app, rc_port))
    _cp_models = [{"catpaw": "LongCat-2.0"}.get(m, m) for m in (_s.get("cp_models") or [])]
    cp = import_catpaw()
    cp.CONFIG["exposed_models"] = list(_cp_models) or list(["LongCat-2.0"])
    cp.CONFIG["log_path"] = str(logs_dir() / "catpaw2openai.log")
    svcs.append(("cp", ProxyService("cp", "cp"), cp.app, cp_port))
    for name, svc, app, port in svcs:
        if not port_free(host, port):
            if reclaim_stale_port(host, port) and port_free(host, port):
                print(f"[{name}] 已关闭残留进程并释放端口 {port}，继续启动")
            else:
                print(f"[{name}] 端口 {port} 被占用，跳过")
                continue
        svc.start(app, host, port)
        print(f"[{name}] listening http://{host}:{port}")

    def _serve_refresh():
        time.sleep(10)
        try:
            bases = {}
            for n, s, _a, p in svcs:
                if n in ("mc", "ca", "cp") and s.running:
                    bases[n] = f"http://127.0.0.1:{p}/v1"
            refresh_models_startup(_s, print, bases)
        except Exception as e:  # noqa: BLE001
            print(f"[models] 启动刷新失败：{e}")
    threading.Thread(target=_serve_refresh, daemon=True).start()
    import signal
    try:
        while any(s.running for _, s, _, _ in svcs):
            stop_evt.wait(1.0)
    except KeyboardInterrupt:
        print("shutting down …")
        for _, s, _, _ in svcs:
            s.stop()
        print("bye")


def main():
    if hasattr(os, "add_dll_directory"):
        pass
    if sys.platform == "win32":
        import multiprocessing
        try:
            multiprocessing.freeze_support()
        except Exception:
            pass

    args = sys.argv[1:]
    if "--selftest" in args:
        sys.exit(run_selftest())
    if "--uismoke" in args:
        run_gui(smoke=True)
        return
    if "--serve" in args:
        def _v(name, default):
            return int(args[args.index(name) + 1]) if name in args else default
        host = "127.0.0.1"
        if "--host" in args:
            host = args[args.index("--host") + 1]
        run_serve(_v("--cb-port", 8787), _v("--mc-port", 9000), _v("--ca-port", 9100), _v("--rc-port", 9200), _v("--cp-port", 9300), host)
        return
    run_gui()


if __name__ == "__main__":
    main()
